1	import { AsyncLocalStorage } from 'node:async_hooks';
2	
3	import { Injectable } from '@nestjs/common';
4	
5	/**
6	 * Actor/request metadata threaded through a single request's async call chain (§14). Roles and
7	 * permissions are mutable arrays on the same store object — `RequestContextMiddleware` seeds an
8	 * empty store before any guard runs; `JwtAuthGuard`/`PermissionsGuard` enrich the SAME object
9	 * in place once they resolve the caller, rather than starting a new `AsyncLocalStorage.run`, so
10	 * every layer downstream (use cases, repositories, audit metadata) observes the same reference.
11	 * A `null` `accountId` means "no authenticated Account" (anonymous request or system actor);
12	 * `isSystemActor` distinguishes worker/scheduler/CLI background execution from an anonymous HTTP
13	 * caller (both have `accountId: null`).
14	 */
15	export interface RequestContextStore {
16	  requestId: string;
17	  correlationId: string;
18	  accountId: string | null;
19	  userProfileId: string | null;
20	  sessionId: string | null;
21	  portal: string | null;
22	  authProvider: string | null;
23	  roles: string[];
24	  permissions: string[];
25	  ipAddress: string | null;
26	  userAgent: string | null;
27	  requestedAt: Date;
28	  isSystemActor: boolean;
29	}
30	
31	export function createEmptyRequestContextStore(
32	  overrides: Partial<RequestContextStore> = {},
33	): RequestContextStore {
34	  return {
35	    requestId: overrides.requestId ?? crypto.randomUUID(),
36	    correlationId: overrides.correlationId ?? overrides.requestId ?? crypto.randomUUID(),
37	    accountId: overrides.accountId ?? null,
38	    userProfileId: overrides.userProfileId ?? null,
39	    sessionId: overrides.sessionId ?? null,
40	    portal: overrides.portal ?? null,
41	    authProvider: overrides.authProvider ?? null,
42	    roles: overrides.roles ?? [],
43	    permissions: overrides.permissions ?? [],
44	    ipAddress: overrides.ipAddress ?? null,
45	    userAgent: overrides.userAgent ?? null,
46	    requestedAt: overrides.requestedAt ?? new Date(),
47	    isSystemActor: overrides.isSystemActor ?? false,
48	  };
49	}
50	
51	@Injectable()
52	export class RequestContext {
53	  private static readonly storage = new AsyncLocalStorage<RequestContextStore>();
54	
55	  run<TResult>(store: RequestContextStore, callback: () => TResult): TResult {
56	    return RequestContext.storage.run(store, callback);
57	  }
58	
59	  get(): RequestContextStore | undefined {
60	    return RequestContext.storage.getStore();
61	  }
62	
63	  /** The actor id to stamp on audit columns: the authenticated Account, or `null` for anonymous/
64	   * system actors — never throws, since not every write happens inside an authenticated request
65	   * (seeders, background jobs). */
66	  currentActorId(): string | null {
67	    return RequestContext.storage.getStore()?.accountId ?? null;
68	  }
69	
70	  /** Runs `work` under a synthetic system-actor context (worker/scheduler/CLI, §14) so audit
71	   * columns and correlation IDs are still populated outside of any HTTP request. */
72	  runAsSystem<TResult>(callback: () => TResult, correlationId?: string): TResult {
73	    return this.run(
74	      createEmptyRequestContextStore({ isSystemActor: true, correlationId }),
75	      callback,
76	    );
77	  }
78	}
