1	import { CorrelationContext } from '@memories/platform/observability';
2	import { Injectable, NestMiddleware } from '@nestjs/common';
3	import { NextFunction, Request, Response } from 'express';
4	
5	import { createEmptyRequestContextStore, RequestContext } from './request-context';
6	
7	/**
8	 * Seeds `RequestContext` for every request BEFORE any guard runs (§14), reusing the request/
9	 * correlation IDs `CorrelationMiddleware` (platform/observability) already established earlier in
10	 * the middleware chain — not generating a second, disagreeing pair of IDs for the same request.
11	 * `accountId`/`userProfileId`/`sessionId`/`portal`/`authProvider`/`roles`/`permissions` start
12	 * empty and are filled in later by `JwtAuthGuard`/`PermissionsGuard` once the caller is resolved.
13	 */
14	@Injectable()
15	export class RequestContextMiddleware implements NestMiddleware {
16	  constructor(private readonly requestContext: RequestContext) {}
17	
18	  use(req: Request, res: Response, next: NextFunction): void {
19	    const correlation = CorrelationContext.current();
20	    const store = createEmptyRequestContextStore({
21	      requestId: correlation?.requestId,
22	      correlationId: correlation?.correlationId,
23	      ipAddress: req.ip ?? null,
24	      userAgent: req.header('user-agent') ?? null,
25	    });
26	
27	    this.requestContext.run(store, () => next());
28	  }
29	}
