1	/** Shared audit trail shape mixed into an aggregate's own props (§6 of MEMORIES-0002). Only add
2	 * here once at least two modules need it — identity-access and user-profiles both do. */
3	export interface AuditableProps {
4	  createdBy: string | null;
5	  createdAt: Date;
6	  updatedBy: string | null;
7	  updatedAt: Date;
8	  deletedBy: string | null;
9	  deletedAt: Date | null;
10	}
11	
12	/** `actorId` is null for system/background actors (worker, scheduler, CLI) — see request context
13	 * system-actor distinction (§14). Aggregates mutate their own audit fields in place afterwards
14	 * (see `Account.touch`) rather than through further helpers here, matching this codebase's
15	 * existing entity-mutation convention (`MediaAsset.markReady` etc. mutate `this.props` directly). */
16	export function createAuditableProps(actorId: string | null, now: Date): AuditableProps {
17	  return {
18	    createdBy: actorId,
19	    createdAt: now,
20	    updatedBy: actorId,
21	    updatedAt: now,
22	    deletedBy: null,
23	    deletedAt: null,
24	  };
25	}
26	
27	export function isAuditablePropsDeleted(props: AuditableProps): boolean {
28	  return props.deletedAt !== null;
29	}
