10	export interface AccountProps extends AuditableProps {
11	  status: AccountStatus;
12	  /** Bumped on password change / forced logout so previously issued access tokens can be
13	   * invalidated without a server-side session store (§13 "token version"). */
14	  tokenVersion: number;
15	}
16	
17	/**
18	 * The single login identity shared by public-web and admin-web (task.md "Background"). Deliberately
19	 * carries NO profile data (name/email/address) — that lives in `user-profiles`' `UserProfile` — and
20	 * NO credential (that lives in `AuthIdentity`); `Account` is only identity + status + authz anchor.
21	 */
22	export class Account extends AggregateRoot<AccountProps> {
23	  static create(props: AccountProps, id?: UniqueEntityId): Account {
24	    return new Account(props, id);
25	  }
26	
27	  get status(): AccountStatus {
28	    return this.props.status;
29	  }
30	
31	  get tokenVersion(): number {
32	    return this.props.tokenVersion;
33	  }
34	
35	  get audit(): AuditableProps {
36	    return this.props;
37	  }
38	
39	  get isDeleted(): boolean {
40	    return this.props.deletedAt !== null;
41	  }
42	
43	  /** Account inactive, locked or deleted must not authenticate or refresh (task.md §2/§9/§13). */
44	  canAuthenticate(): boolean {
45	    return this.props.status === AccountStatus.Active && !this.isDeleted;
46	  }
47	
48	  activate(actorId: string | null, now: Date): void {
49	    this.props.status = AccountStatus.Active;
50	    this.touch(actorId, now);
51	  }
52	
53	  lock(actorId: string | null, now: Date): void {
54	    this.props.status = AccountStatus.Locked;
55	    this.touch(actorId, now);
56	  }
57	
58	  deactivate(actorId: string | null, now: Date): void {
59	    this.props.status = AccountStatus.Inactive;
60	    this.touch(actorId, now);
61	  }
62	
63	  /** Bumps `tokenVersion` so access tokens issued before this call can be treated as stale by
64	   * anything that checks it (§13 permission/token version mechanism). */
65	  incrementTokenVersion(actorId: string | null, now: Date): void {
66	    this.props.tokenVersion += 1;
67	    this.touch(actorId, now);
68	  }
69	
70	  softDelete(actorId: string | null, now: Date): void {
71	    if (this.isDeleted) {
72	      throw DomainError.conflict(
73	        'account_already_deleted',
74	        `Account ${this._id.toString()} is already deleted`,
75	      );
76	    }
77	    this.props.deletedBy = actorId;
78	    this.props.deletedAt = now;
79	    this.touch(actorId, now);
80	  }
81	
82	  private touch(actorId: string | null, now: Date): void {
83	    this.props.updatedBy = actorId;
84	    this.props.updatedAt = now;
85	  }
86	}
