35	export interface CreateAccountInput {
36	  phone: string;
37	  password: string;
38	  fullName: string;
39	  email?: string | undefined;
40	  dateOfBirth?: Date | undefined;
41	  address?: string | undefined;
42	  avatarId?: string | undefined;
43	  /** Actor performing the creation (admin operator), or `null` for an unauthenticated
44	   * self-registration flow. */
45	  actorId: string | null;
46	}
47	
48	export interface CreateAccountOutput {
49	  accountId: string;
50	  userProfileId: string;
51	}
52	
53	/**
54	 * §8 transactional flow: normalize phone -> check duplicate -> hash password -> create Account ->
55	 * create LOCAL AuthIdentity -> create UserProfile -> assign default role, all inside one
56	 * `UnitOfWork.withTransaction`. UserProfile creation delegates to `USER_PROFILE_PROVISIONER`
57	 * (implemented by the `user-profiles` module, injected globally — see
58	 * `libs/platform/security/src/identity.contracts.ts` for why identity-access depends on that port
59	 * instead of importing `@memories/modules/user-profiles` directly: it keeps the module graph
60	 * acyclic since user-profiles' own existence checks use `AccountLookup`, not a direct import back).
61	 */
62	@Injectable()
63	export class CreateAccountUseCase implements UseCase<CreateAccountInput, CreateAccountOutput> {
64	  constructor(
65	    @Inject(UNIT_OF_WORK) private readonly unitOfWork: UnitOfWork,
66	    @Inject(ACCOUNT_REPOSITORY) private readonly accounts: AccountRepository,
67	    @Inject(AUTH_IDENTITY_REPOSITORY) private readonly authIdentities: AuthIdentityRepository,
68	    @Inject(ACCOUNT_ROLE_REPOSITORY) private readonly accountRoles: AccountRoleRepository,
69	    @Inject(ROLE_REPOSITORY) private readonly roles: RoleRepository,
70	    @Inject(PASSWORD_HASHER) private readonly passwordHasher: PasswordHasher,
71	    @Inject(PHONE_NORMALIZER) private readonly phoneNormalizer: PhoneNormalizerPort,
72	    @Inject(USER_PROFILE_PROVISIONER) private readonly userProfileProvisioner: UserProfileProvisioner,
73	    @Inject(ID_GENERATOR) private readonly idGenerator: IdGenerator,
74	    @Inject(CLOCK) private readonly clock: Clock,
75	    private readonly configService: ConfigService,
76	  ) {}
77	
78	  async execute(input: CreateAccountInput): Promise<CreateAccountOutput> {
79	    return this.unitOfWork.withTransaction(async () => {
80	      const auth = this.configService.getOrThrow<AuthConfig>('auth');
81	      const now = this.clock.now();
82	      const phone = this.phoneNormalizer.normalize(input.phone, auth.phone.defaultRegion);
83	
84	      if (await this.authIdentities.existsByProviderAndIdentifier(AuthProvider.Local, phone.value)) {
85	        throw DomainError.conflict('phone_already_exists', `Phone ${phone.value} is already registered`);
86	      }
87	
88	      const passwordHash = await this.passwordHasher.hash(input.password);
89	
90	      const accountId = new UniqueEntityId(this.idGenerator.generate());
91	      const account = Account.create(
92	        {
93	          status: AccountStatus.Active,
94	          tokenVersion: 0,
95	          ...createAuditableProps(input.actorId, now),
96	        },
97	        accountId,
98	      );
99	      await this.accounts.save(account);
100	
101	      const authIdentityId = new UniqueEntityId(this.idGenerator.generate());
102	      const authIdentity = AuthIdentity.create(
103	        {
104	          accountId: accountId.toValue(),
105	          provider: AuthProvider.Local,
106	          identifier: phone.value,
107	          providerSubject: null,
108	          passwordHash,
109	          verifiedAt: null,
110	          ...createAuditableProps(input.actorId, now),
111	        },
112	        authIdentityId,
113	      );
114	      await this.authIdentities.save(authIdentity);
115	
116	      const defaultRole = await this.roles.findByCode(auth.defaultRole.code);
117	      if (!defaultRole) {
118	        throw DomainError.externalDependency(
119	          'default_role_not_seeded',
120	          `Default role "${auth.defaultRole.code}" has not been seeded`,
121	        );
122	      }
123	      await this.accountRoles.assign(accountId.toValue(), defaultRole.id.toValue(), input.actorId, now);
124	
125	      const profile: ProvisionUserProfileOutput = await this.userProfileProvisioner.provision({
126	        accountId: accountId.toValue(),
127	        fullName: input.fullName,
128	        email: input.email,
129	        dateOfBirth: input.dateOfBirth,
130	        address: input.address,
131	        avatarId: input.avatarId,
132	        actorId: input.actorId,
133	      });
134	
135	      return { accountId: accountId.toValue(), userProfileId: profile.userProfileId };
136	    });
137	  }
138	}
