78	    const phone = this.phoneNormalizer.normalize(input.phone, auth.phone.defaultRegion);
79	
80	    // Same generic failure for "phone not found" and "wrong password" (task.md §9 — no account
81	    // enumeration) — the provider itself throws a uniform UnauthorizedException for both.
82	    const { accountId } = await this.authenticationProviders
83	      .resolve(AuthProvider.Local)
84	      .authenticate({ provider: AuthProvider.Local, identifier: phone.value, plainPassword: input.password });
85	
86	    const account = await this.accounts.findById(new UniqueEntityId(accountId));
87	    if (!account || !account.canAuthenticate()) {
88	      throw new ForbiddenException('Account is not active');
89	    }
90	
91	    const requiredPermission = PORTAL_PERMISSION[input.portal];
92	    const hasPortalAccess = await this.permissionChecker.hasPermissions(accountId, [requiredPermission]);
93	    if (!hasPortalAccess) {
94	      throw new ForbiddenException(`Account does not have access to the ${input.portal} portal`);
95	    }
96	
97	    const resolved = await this.permissionChecker.resolvePermissions(accountId);
98	    const userProfileId = await this.userProfileLookup.findProfileIdByAccountId(accountId);
99	
100	    const sessionId = new UniqueEntityId(this.idGenerator.generate());
101	    const now = this.clock.now();
102	
103	    return this.unitOfWork.withTransaction(async () => {
104	      const [accessIssued, refreshIssued] = await Promise.all([
105	        this.tokenService.issueAccessToken({
106	          subject: accountId,
107	          sessionId: sessionId.toValue(),
108	          portal: input.portal,
109	          authProvider: AuthProvider.Local,
110	          userProfileId: userProfileId ?? undefined,
111	        }),
112	        this.tokenService.issueRefreshToken({
113	          subject: accountId,
114	          sessionId: sessionId.toValue(),
115	          portal: input.portal,
116	        }),
117	      ]);
118	
119	      const session = RefreshSession.create(
120	        {
121	          accountId,
122	          portal: input.portal,
123	          authProvider: AuthProvider.Local,
124	          ipAddress: input.ipAddress,
125	          userAgent: input.userAgent,
126	          issuedAt: now,
127	          expiresAt: refreshIssued.expiresAt,
128	          revokedAt: null,
129	          replacedBySessionId: null,
130	        },
131	        sessionId,
132	      );
133	      await this.refreshSessions.save(session);
134	
135	      return {
136	        accountId,
137	        accessToken: accessIssued.token,
138	        refreshToken: refreshIssued.token,
139	        refreshTokenExpiresAt: refreshIssued.expiresAt,
140	        portal: input.portal,
141	        sessionId: sessionId.toValue(),
142	        roles: resolved.roles,
143	        permissions: resolved.permissions,
144	      };
145	    });
146	  }
147	}
