1	import { TokenService, TOKEN_SERVICE } from '@memories/platform/security';
2	import {
3	  CLOCK,
4	  Clock,
5	  ID_GENERATOR,
6	  IdGenerator,
7	  UNIT_OF_WORK,
8	  UniqueEntityId,
9	  UnitOfWork,
10	  UseCase,
11	} from '@memories/shared/kernel';
12	import { ForbiddenException, Inject, Injectable, UnauthorizedException } from '@nestjs/common';
13	
14	import { ACCOUNT_REPOSITORY, AccountRepository } from '../../domain/accounts/account.repository';
15	import { AuthProvider } from '../../domain/auth-identities/auth-provider';
16	import { Portal } from '../../domain/sessions/portal';
17	import { RefreshSession } from '../../domain/sessions/refresh-session';
18	import {
19	  REFRESH_SESSION_REPOSITORY,
20	  RefreshSessionRepository,
21	} from '../../domain/sessions/refresh-session.repository';
22	
23	export interface RefreshSessionInput {
24	  refreshToken: string;
25	  ipAddress: string | null;
26	  userAgent: string | null;
27	}
28	
29	export interface RefreshSessionOutput {
30	  accessToken: string;
31	  refreshToken: string;
32	  refreshTokenExpiresAt: Date;
33	  portal: Portal;
34	  sessionId: string;
35	}
36	
37	/**
38	 * Rotates the refresh token on every use (docs/guides/authentication-flow.md): the old
39	 * `RefreshSession` is revoked and points at the new one via `replacedBySessionId`, so a replayed
40	 * old refresh token (e.g. stolen and used after the legitimate client already rotated) can be
41	 * told apart from a session that merely expired — both fail, but this is what makes theft
42	 * detectable in the session table rather than silently accepted.
43	 */
44	@Injectable()
45	export class RefreshSessionUseCase implements UseCase<RefreshSessionInput, RefreshSessionOutput> {
46	  constructor(
47	    @Inject(ACCOUNT_REPOSITORY) private readonly accounts: AccountRepository,
48	    @Inject(REFRESH_SESSION_REPOSITORY) private readonly refreshSessions: RefreshSessionRepository,
49	    @Inject(TOKEN_SERVICE) private readonly tokenService: TokenService,
50	    @Inject(UNIT_OF_WORK) private readonly unitOfWork: UnitOfWork,
51	    @Inject(ID_GENERATOR) private readonly idGenerator: IdGenerator,
52	    @Inject(CLOCK) private readonly clock: Clock,
53	  ) {}
54	
55	  async execute(input: RefreshSessionInput): Promise<RefreshSessionOutput> {
56	    let claims;
57	    try {
58	      claims = await this.tokenService.verifyRefreshToken(input.refreshToken);
59	    } catch {
60	      throw new UnauthorizedException('Invalid or expired refresh token');
61	    }
62	
63	    const sessionId = typeof claims.sessionId === 'string' ? claims.sessionId : undefined;
64	    const portal = typeof claims.portal === 'string' ? (claims.portal as Portal) : undefined;
65	    if (!sessionId || !portal) {
66	      throw new UnauthorizedException('Malformed refresh token');
67	    }
68	
69	    const now = this.clock.now();
70	    const currentSession = await this.refreshSessions.findById(new UniqueEntityId(sessionId));
71	    if (!currentSession || !currentSession.isActive(now)) {
72	      throw new UnauthorizedException('Refresh session is no longer active');
73	    }
74	
75	    const account = await this.accounts.findById(new UniqueEntityId(claims.subject));
76	    if (!account || !account.canAuthenticate()) {
77	      currentSession.revoke(now);
78	      await this.refreshSessions.save(currentSession);
79	      throw new ForbiddenException('Account is not active');
80	    }
81	
82	    return this.unitOfWork.withTransaction(async () => {
83	      const newSessionId = new UniqueEntityId(this.idGenerator.generate());
84	
85	      const [accessIssued, refreshIssued] = await Promise.all([
86	        this.tokenService.issueAccessToken({
87	          subject: claims.subject,
88	          sessionId: newSessionId.toValue(),
89	          portal,
90	          authProvider: AuthProvider.Local,
91	        }),
92	        this.tokenService.issueRefreshToken({
93	          subject: claims.subject,
94	          sessionId: newSessionId.toValue(),
95	          portal,
96	        }),
97	      ]);
98	
99	      currentSession.revoke(now, newSessionId.toValue());
100	      await this.refreshSessions.save(currentSession);
101	
102	      const newSession = RefreshSession.create(
103	        {
104	          accountId: claims.subject,
105	          portal,
106	          authProvider: AuthProvider.Local,
107	          ipAddress: input.ipAddress,
108	          userAgent: input.userAgent,
109	          issuedAt: now,
110	          expiresAt: refreshIssued.expiresAt,
111	          revokedAt: null,
112	          replacedBySessionId: null,
113	        },
114	        newSessionId,
115	      );
116	      await this.refreshSessions.save(newSession);
117	
118	      return {
119	        accessToken: accessIssued.token,
120	        refreshToken: refreshIssued.token,
121	        refreshTokenExpiresAt: refreshIssued.expiresAt,
122	        portal,
123	        sessionId: newSessionId.toValue(),
124	      };
125	    });
126	  }
127	}
