19	export interface ChangeAccountStatusInput {
20	  accountId: string;
21	  status: AccountStatus;
22	  actorId: string | null;
23	}
24	
25	/**
26	 * §16 `PATCH /accounts/:accountId/status`. Any transition away from `ACTIVE` revokes every
27	 * outstanding session for the account — AC #32 only calls out lock/delete explicitly, but
28	 * `INACTIVE` is just as unable to authenticate (§2), so leaving its sessions live would be
29	 * inconsistent with "Account inactive, locked hoặc deleted không được đăng nhập/refresh" (§2, §9).
30	 */
31	@Injectable()
32	export class ChangeAccountStatusUseCase implements UseCase<ChangeAccountStatusInput, void> {
33	  constructor(
34	    @Inject(ACCOUNT_REPOSITORY) private readonly accounts: AccountRepository,
35	    @Inject(REFRESH_SESSION_REPOSITORY) private readonly refreshSessions: RefreshSessionRepository,
36	    @Inject(UNIT_OF_WORK) private readonly unitOfWork: UnitOfWork,
37	    @Inject(CLOCK) private readonly clock: Clock,
38	  ) {}
39	
40	  async execute(input: ChangeAccountStatusInput): Promise<void> {
41	    await this.unitOfWork.withTransaction(async () => {
42	      const account = await this.accounts.findById(new UniqueEntityId(input.accountId));
43	      if (!account) {
44	        throw DomainError.notFound('account_not_found', `Account ${input.accountId} was not found`);
45	      }
46	
47	      const now = this.clock.now();
48	      switch (input.status) {
49	        case AccountStatus.Active:
50	          account.activate(input.actorId, now);
51	          break;
52	        case AccountStatus.Locked:
53	          account.lock(input.actorId, now);
54	          break;
55	        case AccountStatus.Inactive:
56	          account.deactivate(input.actorId, now);
57	          break;
58	      }
59	      await this.accounts.save(account);
60	
61	      if (input.status !== AccountStatus.Active) {
62	        await this.refreshSessions.revokeAllForAccount(input.accountId, now);
63	      }
64	    });
65	  }
66	}
