39	
40	  get objectKey(): string {
41	    return this.props.objectKey;
42	  }
43	
44	  get status(): MediaAssetStatus {
45	    return this.props.status;
46	  }
47	
48	  get mimeType(): string {
49	    return this.props.mimeType;
50	  }
51	
52	  get sizeBytes(): number {
53	    return this.props.sizeBytes;
54	  }
