58	  }
59	
60	  get failureReason(): string | undefined {
61	    return this.props.failureReason;
62	  }
63	
64	  get currentJobId(): string | undefined {
65	    return this.props.currentJobId;
66	  }
67	
68	  get confirmedEtag(): string | undefined {
69	    return this.props.confirmedEtag;
70	  }
