17	@Injectable()
18	export class TypeOrmMediaAssetRepository implements MediaAssetRepository {
19	  private readonly mapper = new MediaAssetMapper();
20	
21	  constructor(
22	    @InjectRepository(MediaAssetOrmEntity)
23	    private readonly repository: TypeOrmRepository<MediaAssetOrmEntity>,
24	    private readonly queryRunnerContext: TypeOrmQueryRunnerContext,
25	  ) {}
