27	  /** Joins the ambient UnitOfWork transaction when one is active (e.g. confirm-upload's
28	   * status-write + outbox-insert must commit or roll back together), otherwise falls back to
29	   * the default connection. */
30	  private repositoryFor(): TypeOrmRepository<MediaAssetOrmEntity> {
31	    const queryRunner = this.queryRunnerContext.get();
32	    return queryRunner ? queryRunner.manager.getRepository(MediaAssetOrmEntity) : this.repository;
33	  }
34	
35	  async findById(id: UniqueEntityId): Promise<MediaAsset | null> {
36	    const raw = await this.repositoryFor().findOne({ where: { id: id.toValue() } });
37	    return raw ? this.mapper.toDomain(raw) : null;
38	  }
39	
40	  async save(aggregate: MediaAsset): Promise<void> {
41	    await this.repositoryFor().save(this.mapper.toPersistence(aggregate));
42	  }
43	
44	  async delete(id: UniqueEntityId): Promise<void> {
45	    await this.repositoryFor().delete({ id: id.toValue() });
46	  }
47	
48	  async transitionStatus(
49	    id: UniqueEntityId,
50	    expected: MediaAssetStatusExpectation,
51	    next: MediaAssetStatusTransition,
52	  ): Promise<boolean> {
53	    const result = await this.repositoryFor().update(
54	      {
55	        id: id.toValue(),
56	        status: expected.status,
57	        ...(expected.jobId !== undefined && { currentJobId: expected.jobId }),
58	      },
59	      {
60	        status: next.status,
61	        ...(next.processedObjectKey !== undefined && {
62	          processedObjectKey: next.processedObjectKey,
63	        }),
64	        ...(next.failureReason !== undefined && { failureReason: next.failureReason }),
65	        ...(next.jobId !== undefined && { currentJobId: next.jobId }),
66	        ...(next.confirmedEtag !== undefined && { confirmedEtag: next.confirmedEtag }),
67	      },
68	    );
69	    return (result.affected ?? 0) > 0;
70	  }
