31	    const auth = this.configService.getOrThrow<AuthConfig>('auth');
32	    return this.jwtService.verifyAsync<TokenClaims>(token, { secret: auth.jwt.refreshSecret });
33	  }
34	
35	  private async sign(claims: TokenClaims, secret: string, expiresIn: string): Promise<IssuedToken> {
36	    const token = await this.jwtService.signAsync(claims, { secret, expiresIn });
37	    return { token, expiresAt: new Date(Date.now() + msFromDuration(expiresIn)) };
38	  }
39	}
