41	function msFromDuration(duration: string): number {
42	  const match = /^(\d+)(s|m|h|d)$/.exec(duration);
43	  if (!match) {
44	    return 0;
45	  }
46	  const value = Number(match[1]);
47	  const unit = match[2];
48	  const unitMs = { s: 1000, m: 60_000, h: 3_600_000, d: 86_400_000 }[unit as 's' | 'm' | 'h' | 'd'];
49	  return value * unitMs;
50	}
