1	import { AsyncLocalStorage } from 'node:async_hooks';
2	
3	import { UnitOfWork } from '@memories/shared/kernel';
4	import { Injectable } from '@nestjs/common';
5	import { DataSource, QueryRunner } from 'typeorm';
6	
7	/**
8	 * AsyncLocalStorage-backed so concurrent requests each see only their own active transaction's
9	 * QueryRunner. A plain mutable field (the original scaffolded shape) would be a shared singleton
10	 * across every concurrent request: one request's `withTransaction` call would silently overwrite
11	 * another's in-flight QueryRunner, corrupting whichever transaction started first. This had never
12	 * been exercised by any real repository until the confirm-upload/outbox work needed it for real.
13	 */
14	@Injectable()
15	export class TypeOrmQueryRunnerContext {
16	  private static readonly storage = new AsyncLocalStorage<QueryRunner>();
17	
18	  run<TResult>(queryRunner: QueryRunner, callback: () => Promise<TResult>): Promise<TResult> {
19	    return TypeOrmQueryRunnerContext.storage.run(queryRunner, callback);
20	  }
21	
22	  get(): QueryRunner | undefined {
23	    return TypeOrmQueryRunnerContext.storage.getStore();
24	  }
25	}
26	
27	@Injectable()
28	export class TypeOrmUnitOfWork implements UnitOfWork {
29	  constructor(
30	    private readonly dataSource: DataSource,
31	    private readonly context: TypeOrmQueryRunnerContext,
32	  ) {}
33	
34	  async withTransaction<TResult>(work: () => Promise<TResult>): Promise<TResult> {
35	    const queryRunner = this.dataSource.createQueryRunner();
36	    // `connect()` checks a connection out of the pool — once it resolves, that connection MUST
37	    // be released no matter what happens next, so everything from here on is wrapped in a
38	    // try/finally. `startTransaction()` used to run BEFORE this try/finally: if it rejected
39	    // (e.g. the connection dropped between connect() and BEGIN), the checked-out connection was
40	    // never released, leaking it from the pool — repeated failures during a degraded database
41	    // could exhaust the pool entirely and prevent any recovery.
42	    await queryRunner.connect();
43	    try {
44	      await queryRunner.startTransaction();
45	      try {
46	        const result = await this.context.run(queryRunner, work);
47	        await queryRunner.commitTransaction();
48	        return result;
49	      } catch (error) {
50	        // Only reached once `startTransaction()` has actually succeeded, so a transaction is
51	        // genuinely active here — calling `rollbackTransaction()` for a failure that happened
52	        // before any transaction started would itself be an invalid operation.
53	        await queryRunner.rollbackTransaction();
54	        throw error;
55	      }
56	    } finally {
57	      await queryRunner.release();
58	    }
59	  }
60	}
