import { Repository, UniqueEntityId } from '@memories/shared/kernel';

import { AccountStatus } from './account-status';
import { Account } from './account';

export interface AccountListFilter {
  status?: AccountStatus;
  /** Matches an `AuthIdentity.provider` the account has (e.g. `LOCAL`). */
  provider?: string;
  /** Substring match against the account's LOCAL phone identifier. */
  phoneSearch?: string;
  page: number;
  pageSize: number;
  sortBy: 'createdAt' | 'updatedAt';
  sortDirection: 'ASC' | 'DESC';
}

export interface AccountListItem {
  account: Account;
  phone: string | null;
}

export interface AccountRepository extends Repository<Account> {
  /** `findById` (from `Repository<Account>`) excludes soft-deleted rows — this variant is for the
   * few flows (e.g. idempotency checks) that must still see a deleted Account. */
  findByIdIncludingDeleted(id: UniqueEntityId): Promise<Account | null>;
  list(filter: AccountListFilter): Promise<{ items: AccountListItem[]; total: number }>;
}

export const ACCOUNT_REPOSITORY = Symbol('ACCOUNT_REPOSITORY');

