18	/**
19	 * One login method for an `Account` (§3). An Account can have several — one per provider it has
20	 * linked — but only `LOCAL` is exercised end-to-end in this epic.
21	 */
22	export class AuthIdentity extends AggregateRoot<AuthIdentityProps> {
23	  static create(props: AuthIdentityProps, id?: UniqueEntityId): AuthIdentity {
24	    if (props.provider === AuthProvider.Local) {
25	      if (!props.identifier) {
26	        throw DomainError.validation('phone_required', 'LOCAL auth identity requires a phone identifier');
27	      }
28	      if (!props.passwordHash) {
29	        throw DomainError.validation('password_required', 'LOCAL auth identity requires a password hash');
30	      }
31	    }
32	    return new AuthIdentity(props, id);
33	  }
