63	  changePasswordHash(passwordHash: string, actorId: string | null, now: Date): void {
64	    if (this.props.provider !== AuthProvider.Local) {
65	      throw DomainError.businessRule(
66	        'password_change_not_supported',
67	        `Auth identity provider "${this.props.provider}" does not support password changes`,
68	      );
69	    }
70	    this.props.passwordHash = passwordHash;
71	    this.touch(actorId, now);
72	  }
