74	  changeIdentifier(identifier: string, actorId: string | null, now: Date): void {
75	    if (this.props.provider !== AuthProvider.Local) {
76	      throw DomainError.businessRule(
77	        'identifier_change_not_supported',
78	        `Auth identity provider "${this.props.provider}" does not support changing the identifier`,
79	      );
