import { CLOCK, Clock, UniqueEntityId, UseCase } from '@memories/shared/kernel';
import { Inject, Injectable } from '@nestjs/common';

import {
  REFRESH_SESSION_REPOSITORY,
  RefreshSessionRepository,
} from '../../domain/sessions/refresh-session.repository';

export interface LogoutInput {
  sessionId: string;
}

/** Idempotent: logging out a session that's already revoked or gone is not an error — the caller
 * only cares that the session is inactive afterwards. */
@Injectable()
export class LogoutUseCase implements UseCase<LogoutInput, void> {
  constructor(
    @Inject(REFRESH_SESSION_REPOSITORY) private readonly refreshSessions: RefreshSessionRepository,
    @Inject(CLOCK) private readonly clock: Clock,
  ) {}

  async execute(input: LogoutInput): Promise<void> {
    const session = await this.refreshSessions.findById(new UniqueEntityId(input.sessionId));
    if (!session) {
      return;
    }
    session.revoke(this.clock.now());
    await this.refreshSessions.save(session);
  }
}

