32	 * change/reset, forcing re-login everywhere else the Account is currently signed in. */
33	@Injectable()
34	export class ChangeAccountPasswordUseCase implements UseCase<ChangeAccountPasswordInput, void> {
35	  constructor(
36	    @Inject(ACCOUNT_REPOSITORY) private readonly accounts: AccountRepository,
