45	    await this.unitOfWork.withTransaction(async () => {
46	      const now = this.clock.now();
47	
48	      const account = await this.accounts.findById(new UniqueEntityId(input.accountId));
49	      if (!account) {
50	        throw DomainError.notFound('account_not_found', `Account ${input.accountId} was not found`);
51	      }
52	
53	      const identities = await this.authIdentities.findAllByAccountId(input.accountId);
