import { Injectable } from '@nestjs/common';

import { AccountDetail, GetAccountInput, GetAccountUseCase } from './get-account.use-case';

/**
 * `PATCH /accounts/:accountId` (§16). `Account` intentionally has no client-editable attributes
 * beyond `status`/phone/password — each of those already has its own dedicated, narrowly-scoped
 * endpoint (§16 "Không cập nhật password qua generic update DTO", "Không cập nhật phone qua
 * generic update DTO") specifically so a generic update can't be used to bypass their extra
 * validation (uniqueness, re-hashing, session revocation). This use case therefore has nothing
 * generic left to mutate today; it exists so the route/permission gate (`account.update`) is in
 * place and simply returns the current detail unchanged. Extend it (and `UpdateAccountDto`) the
 * day `Account` grows a genuinely generic field.
 */
export interface UpdateAccountInput {
  accountId: string;
}

@Injectable()
export class UpdateAccountUseCase implements UseCase<UpdateAccountInput, AccountDetail> {
  constructor(private readonly getAccount: GetAccountUseCase) {}

