  issueAccessToken(claims: TokenClaims): Promise<IssuedToken>;
  issueRefreshToken(claims: TokenClaims): Promise<IssuedToken>;
  verifyAccessToken(token: string): Promise<TokenClaims>;
  verifyRefreshToken(token: string): Promise<TokenClaims>;
}

export const TOKEN_SERVICE = Symbol('TOKEN_SERVICE');

