import { Column, Entity, PrimaryColumn } from 'typeorm';

import { MediaAssetStatus } from '../../domain/media-asset/media-asset-status';

/** Persistence shape only — never imported by domain. Kept separate from `MediaAsset` on purpose. */
@Entity({ name: 'media_assets' })
export class MediaAssetOrmEntity {
  @PrimaryColumn('uuid')
  id!: string;

  @Column({ name: 'owner_id', type: 'uuid' })
  ownerId!: string;

  @Column()
  bucket!: string;

  @Column({ name: 'object_key' })
  objectKey!: string;

  @Column({ name: 'mime_type' })
  mimeType!: string;

  @Column({ name: 'size_bytes', type: 'bigint' })
  sizeBytes!: number;

  @Column({ type: 'enum', enum: MediaAssetStatus, default: MediaAssetStatus.Pending })
  status!: MediaAssetStatus;

  // `type` is explicit here (unlike the required string columns above): reflect-metadata
  // collapses a `string | undefined` property type to `Object` at design-time, which TypeORM
  // cannot map to a Postgres column type without an explicit hint.
  @Column({ name: 'processed_object_key', type: 'varchar', nullable: true })
  processedObjectKey?: string | undefined;

  // `| null` (not just `| undefined`): transitionStatus's CAS needs to explicitly set this
  // column back to SQL NULL (clearing a stale reason from a prior failed attempt), which TypeORM
  // only accepts as a literal `null` value in an update payload, not `undefined`.
  @Column({ name: 'failure_reason', type: 'varchar', nullable: true })
  failureReason?: string | null | undefined;

  @Column({ name: 'current_job_id', type: 'varchar', nullable: true })
  currentJobId?: string | undefined;

  @Column({ name: 'confirmed_etag', type: 'varchar', nullable: true })
  confirmedEtag?: string | undefined;
}

