import { Mapper, UniqueEntityId } from '@memories/shared/kernel';

import { MediaAsset } from '../../domain/media-asset/media-asset';

import { MediaAssetOrmEntity } from './media-asset.orm-entity';

export class MediaAssetMapper implements Mapper<MediaAsset, MediaAssetOrmEntity> {
  toDomain(raw: MediaAssetOrmEntity): MediaAsset {
    return MediaAsset.create(
      {
        ownerId: raw.ownerId,
        bucket: raw.bucket,
        objectKey: raw.objectKey,
        mimeType: raw.mimeType,
        sizeBytes: Number(raw.sizeBytes),
        status: raw.status,
        processedObjectKey: raw.processedObjectKey,
        // Normalize a NULL column read as JS `null` back to `undefined` — the domain's own type
        // only ever represents "no failure reason" as `undefined`, never `null`.
        failureReason: raw.failureReason ?? undefined,
        currentJobId: raw.currentJobId,
        confirmedEtag: raw.confirmedEtag,
      },
      new UniqueEntityId(raw.id),
    );
  }

  toPersistence(domain: MediaAsset): MediaAssetOrmEntity {
    const entity = new MediaAssetOrmEntity();
    entity.id = domain.id.toValue();
    entity.ownerId = domain.ownerId;
    entity.bucket = domain.bucket;
    entity.objectKey = domain.objectKey;
    entity.mimeType = domain.mimeType;
    entity.sizeBytes = domain.sizeBytes;
    entity.status = domain.status;
    entity.processedObjectKey = domain.processedObjectKey;
    entity.failureReason = domain.failureReason;
    entity.currentJobId = domain.currentJobId;
    entity.confirmedEtag = domain.confirmedEtag;
    return entity;
  }

  toDto(domain: MediaAsset) {
    return {
      id: domain.id.toValue(),
      status: domain.status,
    };
  }
}

