import { TypeOrmQueryRunnerContext } from '@memories/platform/database';
import { UniqueEntityId } from '@memories/shared/kernel';
import { Injectable } from '@nestjs/common';
import { InjectRepository } from '@nestjs/typeorm';
import { Repository as TypeOrmRepository } from 'typeorm';

import { MediaAsset } from '../../domain/media-asset/media-asset';
import {
  MediaAssetRepository,
  MediaAssetStatusExpectation,
  MediaAssetStatusTransition,
} from '../../domain/media-asset/media-asset.repository';

import { MediaAssetMapper } from './media-asset.mapper';
import { MediaAssetOrmEntity } from './media-asset.orm-entity';

@Injectable()
export class TypeOrmMediaAssetRepository implements MediaAssetRepository {
  private readonly mapper = new MediaAssetMapper();

  constructor(
    @InjectRepository(MediaAssetOrmEntity)
    private readonly repository: TypeOrmRepository<MediaAssetOrmEntity>,
    private readonly queryRunnerContext: TypeOrmQueryRunnerContext,
  ) {}

  /** Joins the ambient UnitOfWork transaction when one is active (e.g. confirm-upload's
   * status-write + outbox-insert must commit or roll back together), otherwise falls back to
   * the default connection. */
  private repositoryFor(): TypeOrmRepository<MediaAssetOrmEntity> {
    const queryRunner = this.queryRunnerContext.get();
    return queryRunner ? queryRunner.manager.getRepository(MediaAssetOrmEntity) : this.repository;
  }

  async findById(id: UniqueEntityId): Promise<MediaAsset | null> {
    const raw = await this.repositoryFor().findOne({ where: { id: id.toValue() } });
    return raw ? this.mapper.toDomain(raw) : null;
  }

  async save(aggregate: MediaAsset): Promise<void> {
    await this.repositoryFor().save(this.mapper.toPersistence(aggregate));
  }

  async delete(id: UniqueEntityId): Promise<void> {
    await this.repositoryFor().delete({ id: id.toValue() });
  }

  async transitionStatus(
    id: UniqueEntityId,
    expected: MediaAssetStatusExpectation,
    next: MediaAssetStatusTransition,
  ): Promise<boolean> {
    const result = await this.repositoryFor().update(
      {
        id: id.toValue(),
        status: expected.status,
        ...(expected.jobId !== undefined && { currentJobId: expected.jobId }),
      },
      {
        status: next.status,
        ...(next.processedObjectKey !== undefined && {
          processedObjectKey: next.processedObjectKey,
        }),
        ...(next.failureReason !== undefined && { failureReason: next.failureReason }),
        ...(next.jobId !== undefined && { currentJobId: next.jobId }),
        ...(next.confirmedEtag !== undefined && { confirmedEtag: next.confirmedEtag }),
      },
    );
    return (result.affected ?? 0) > 0;
  }
}

