import { CurrentUser, JwtAuthGuard, RequestUser } from '@memories/platform/security';
import { Body, Controller, Get, HttpCode, HttpStatus, Param, Post, UseGuards } from '@nestjs/common';
import { ApiBearerAuth, ApiParam, ApiResponse, ApiTags } from '@nestjs/swagger';

import { ConfirmMediaUploadUseCase } from '../../application/use-cases/confirm-media-upload.use-case';
import { CreateMediaAssetUseCase } from '../../application/use-cases/create-media-asset.use-case';
import { GetMediaAssetUseCase } from '../../application/use-cases/get-media-asset.use-case';

import { ConfirmUploadParamsDto } from './confirm-upload.dto';
import { CreateMediaAssetDto } from './create-media-asset.dto';
import {
  ConfirmUploadResponseDto,
  CreateMediaAssetResponseDto,
  GetMediaAssetResponseDto,
} from './media-asset-response.dto';

@ApiTags('media')
@ApiBearerAuth()
@UseGuards(JwtAuthGuard)
@Controller('media')
export class MediaController {
  constructor(
    private readonly createMediaAsset: CreateMediaAssetUseCase,
    private readonly confirmMediaUpload: ConfirmMediaUploadUseCase,
    private readonly getMediaAsset: GetMediaAssetUseCase,
  ) {}

  @Post()
  @ApiResponse({ status: HttpStatus.CREATED, type: CreateMediaAssetResponseDto })
  async create(
    @CurrentUser() user: RequestUser,
    @Body() dto: CreateMediaAssetDto,
  ): Promise<CreateMediaAssetResponseDto> {
    return this.createMediaAsset.execute({
      ownerId: user.id,
      mimeType: dto.mimeType,
      sizeBytes: dto.sizeBytes,
    });
  }

  @Post(':mediaAssetId/confirm-upload')
  @HttpCode(HttpStatus.ACCEPTED)
  @ApiParam({ name: 'mediaAssetId', type: String, format: 'uuid' })
  @ApiResponse({ status: HttpStatus.ACCEPTED, type: ConfirmUploadResponseDto })
  async confirmUpload(
    @CurrentUser() user: RequestUser,
    @Param() params: ConfirmUploadParamsDto,
  ): Promise<ConfirmUploadResponseDto> {
    await this.confirmMediaUpload.execute({ mediaAssetId: params.mediaAssetId, actorId: user.id });
    return { status: 'processing' };
  }

  @Get(':mediaAssetId')
  @ApiParam({ name: 'mediaAssetId', type: String, format: 'uuid' })
  @ApiResponse({ status: HttpStatus.OK, type: GetMediaAssetResponseDto })
  async get(
    @CurrentUser() user: RequestUser,
    @Param() params: ConfirmUploadParamsDto,
  ): Promise<GetMediaAssetResponseDto> {
    return this.getMediaAsset.execute({ mediaAssetId: params.mediaAssetId, actorId: user.id });
  }
}

