export class GetMediaAssetResponseDto {
  @ApiProperty() mediaAssetId!: string;
  @ApiProperty({ enum: ['pending', 'processing', 'ready', 'failed'] }) status!: string;
  @ApiProperty() objectKey!: string;
  // `type` is explicit here: reflect-metadata collapses a `string | undefined` property type to
  // `Object` at design-time, same root cause as the TypeORM column-type gap fixed in
