export enum DomainErrorKind {
  Validation = 'validation',
  BusinessRule = 'business_rule',
  NotFound = 'not_found',
  Conflict = 'conflict',
  Forbidden = 'forbidden',
  ExternalDependency = 'external_dependency',
}

export class DomainError extends Error {
  constructor(
    readonly kind: DomainErrorKind,
    message: string,
    readonly code: string,
    readonly details?: Record<string, unknown>,
  ) {
    super(message);
    this.name = 'DomainError';
  }

  static validation(code: string, message: string, details?: Record<string, unknown>): DomainError {
    return new DomainError(DomainErrorKind.Validation, message, code, details);
  }

  static businessRule(
    code: string,
    message: string,
    details?: Record<string, unknown>,
  ): DomainError {
    return new DomainError(DomainErrorKind.BusinessRule, message, code, details);
  }

  static notFound(code: string, message: string, details?: Record<string, unknown>): DomainError {
    return new DomainError(DomainErrorKind.NotFound, message, code, details);
  }

  static conflict(code: string, message: string, details?: Record<string, unknown>): DomainError {
    return new DomainError(DomainErrorKind.Conflict, message, code, details);
  }

  static forbidden(code: string, message: string, details?: Record<string, unknown>): DomainError {
    return new DomainError(DomainErrorKind.Forbidden, message, code, details);
  }

  static externalDependency(
    code: string,
    message: string,
    details?: Record<string, unknown>,
  ): DomainError {
    return new DomainError(DomainErrorKind.ExternalDependency, message, code, details);
  }
}

