import { DomainError, DomainErrorKind } from '@memories/shared/kernel';
import {
  ArgumentsHost,
  Catch,
  ExceptionFilter,
  HttpException,
  HttpStatus,
  Logger,
} from '@nestjs/common';
import { Request, Response } from 'express';

const DOMAIN_ERROR_STATUS: Record<DomainErrorKind, HttpStatus> = {
  [DomainErrorKind.Validation]: HttpStatus.BAD_REQUEST,
  [DomainErrorKind.BusinessRule]: HttpStatus.UNPROCESSABLE_ENTITY,
  [DomainErrorKind.NotFound]: HttpStatus.NOT_FOUND,
  [DomainErrorKind.Conflict]: HttpStatus.CONFLICT,
  [DomainErrorKind.Forbidden]: HttpStatus.FORBIDDEN,
  [DomainErrorKind.ExternalDependency]: HttpStatus.BAD_GATEWAY,
};

export interface ErrorResponseBody {
  statusCode: number;
  errorCode: string;
  message: string;
  correlationId?: string | undefined;
  stack?: string | undefined;
}

/**
 * Never leaks a stack trace outside of local/test/development, and always returns a stable
 * `errorCode` so the frontend can map errors without parsing free-text messages (§14).
 */
@Catch()
export class GlobalExceptionFilter implements ExceptionFilter {
  private readonly logger = new Logger(GlobalExceptionFilter.name);

  constructor(private readonly isProduction: boolean) {}

  catch(exception: unknown, host: ArgumentsHost): void {
    const ctx = host.switchToHttp();
    const response = ctx.getResponse<Response>();
    const request = ctx.getRequest<Request>();

    const body = this.toResponseBody(exception);
    this.logger.error(`${request.method} ${request.url} -> ${body.statusCode} ${body.errorCode}`);
    response.status(body.statusCode).json(body);
  }

  private toResponseBody(exception: unknown): ErrorResponseBody {
    if (exception instanceof DomainError) {
      return {
        statusCode: DOMAIN_ERROR_STATUS[exception.kind],
        errorCode: exception.code,
        message: exception.message,
        stack: this.isProduction ? undefined : exception.stack,
      };
    }

    if (exception instanceof HttpException) {
      return {
        statusCode: exception.getStatus(),
        errorCode: 'http_exception',
        message: exception.message,
        stack: this.isProduction ? undefined : exception.stack,
      };
    }

    const error = exception instanceof Error ? exception : new Error('Unknown error');
    return {
      statusCode: HttpStatus.INTERNAL_SERVER_ERROR,
      errorCode: 'internal_error',
      message: this.isProduction ? 'Internal server error' : error.message,
      stack: this.isProduction ? undefined : error.stack,
    };
  }
}

