import { DatabaseConfig } from '@memories/platform/configuration';
import { DynamicModule, Module } from '@nestjs/common';
import { ConfigService } from '@nestjs/config';
import { TypeOrmModule } from '@nestjs/typeorm';
import { DataSource } from 'typeorm';

import { DatabaseHealthIndicator } from './database.health-indicator';
import { UNIT_OF_WORK } from './database.tokens';
import { buildTypeOrmOptions } from './typeorm-options.factory';
import { TypeOrmQueryRunnerContext, TypeOrmUnitOfWork } from './typeorm-unit-of-work';

const SHARED_PROVIDERS = [
  DatabaseHealthIndicator,
  TypeOrmQueryRunnerContext,
  { provide: UNIT_OF_WORK, useClass: TypeOrmUnitOfWork },
];

@Module({})
export class DatabaseModule {
  /** Used by api/worker/scheduler/cli — all read the same typed DatabaseConfig from ConfigurationModule. */
  static register(): DynamicModule {
    return {
      module: DatabaseModule,
      global: true,
      imports: [
        TypeOrmModule.forRootAsync({
          inject: [ConfigService],
          useFactory: (configService: ConfigService) =>
            buildTypeOrmOptions(configService.getOrThrow<DatabaseConfig>('database')),
          dataSourceFactory: async (options) => new DataSource(options!).initialize(),
        }),
      ],
      providers: SHARED_PROVIDERS,
      exports: [TypeOrmModule, ...SHARED_PROVIDERS],
    };
  }

  static registerAsync(
    optionsFactory: (configService: ConfigService) => Promise<DatabaseConfig> | DatabaseConfig,
  ): DynamicModule {
    return {
      module: DatabaseModule,
      global: true,
      imports: [
        TypeOrmModule.forRootAsync({
          inject: [ConfigService],
          useFactory: async (configService: ConfigService) =>
            buildTypeOrmOptions(await optionsFactory(configService)),
        }),
      ],
      providers: SHARED_PROVIDERS,
      exports: [TypeOrmModule, ...SHARED_PROVIDERS],
    };
  }
}

import 'reflect-metadata';
import { config as loadDotenv } from 'dotenv';
import { DataSource } from 'typeorm';

/**
 * Standalone DataSource used only by the TypeORM CLI (`npm run migration:*`).
 * It runs outside the Nest DI container, before any application process bootstraps,
 * so it loads `.env` directly instead of going through ConfigurationModule.
 */
loadDotenv();

export const AppDataSource = new DataSource({
  type: 'postgres',
  host: process.env.DATABASE_HOST ?? 'localhost',
  port: Number(process.env.DATABASE_PORT ?? 5432),
  username: process.env.DATABASE_USERNAME ?? '',
  password: process.env.DATABASE_PASSWORD ?? '',
  database: process.env.DATABASE_NAME ?? '',
  ssl: process.env.DATABASE_SSL === 'true' ? { rejectUnauthorized: false } : false,
  synchronize: false,
  entities: ['libs/modules/**/*.orm-entity.ts', 'libs/platform/**/*.orm-entity.ts'],
  migrations: ['libs/platform/database/src/migrations/*.ts'],
  migrationsTableName: 'migrations',
});

