import { MigrationInterface, QueryRunner } from 'typeorm';

/** Backs `libs/modules/media` — the module used to demonstrate the BullMQ flow end-to-end. */
export class CreateMediaAssets1722510000000 implements MigrationInterface {
  name = 'CreateMediaAssets1722510000000';

  public async up(queryRunner: QueryRunner): Promise<void> {
    await queryRunner.query(`
      CREATE TYPE "media_assets_status_enum" AS ENUM ('pending', 'processing', 'ready', 'failed')
    `);
    await queryRunner.query(`
      CREATE TABLE "media_assets" (
        "id" uuid NOT NULL,
        "owner_id" uuid NOT NULL,
        "bucket" character varying NOT NULL,
        "object_key" character varying NOT NULL,
        "mime_type" character varying NOT NULL,
        "size_bytes" bigint NOT NULL,
        "status" "media_assets_status_enum" NOT NULL DEFAULT 'pending',
        "processed_object_key" character varying,
        "failure_reason" character varying,
        "current_job_id" character varying,
        CONSTRAINT "PK_media_assets_id" PRIMARY KEY ("id")
      )
    `);
    await queryRunner.query(`
      CREATE INDEX "IDX_media_assets_owner_id" ON "media_assets" ("owner_id")
    `);
  }

  public async down(queryRunner: QueryRunner): Promise<void> {
    await queryRunner.query(`DROP INDEX "IDX_media_assets_owner_id"`);
    await queryRunner.query(`DROP TABLE "media_assets"`);
    await queryRunner.query(`DROP TYPE "media_assets_status_enum"`);
  }
}

