import 'reflect-metadata';
import { AppConfig, SecurityConfig } from '@memories/platform/configuration';
import { ConfigService } from '@nestjs/config';
import { NestFactory } from '@nestjs/core';
import { SwaggerModule } from '@nestjs/swagger';
import { Logger } from 'nestjs-pino';

import { AppModule } from './app.module';
import { configureApp } from './configure-app';
import { buildOpenApiDocument } from './openapi';

async function bootstrap(): Promise<void> {
  const app = await NestFactory.create(AppModule, { bufferLogs: true });
  app.useLogger(app.get(Logger));

  const configService = app.get(ConfigService);
  const appConfig = configService.getOrThrow<AppConfig>('app');
  const securityConfig = configService.getOrThrow<SecurityConfig>('security');

  configureApp(app, appConfig);
  app.enableShutdownHooks();

  if (securityConfig.swaggerEnabled) {
    SwaggerModule.setup('docs', app, buildOpenApiDocument(app, appConfig));
  }

  await app.listen(appConfig.port);
}

bootstrap();

