import { DomainError } from '@memories/shared/kernel';
import { Injectable } from '@nestjs/common';
import { CountryCode, parsePhoneNumberFromString } from 'libphonenumber-js';

import { PhoneNormalizerPort } from '../../application/ports/phone-normalizer.port';
import { PhoneNumber } from '../../domain/value-objects/phone-number.vo';

/** Backed by libphonenumber-js — kept out of `domain`/`application` (see the port's doc-comment).
 * `defaultRegion` (task.md §9, e.g. `VN`) is only used when `raw` has no explicit country code. */
@Injectable()
export class PhoneNormalizer implements PhoneNormalizerPort {
  normalize(raw: string, defaultRegion: string): PhoneNumber {
    const parsed = parsePhoneNumberFromString(raw, defaultRegion as CountryCode);
    if (!parsed || !parsed.isValid()) {
      throw DomainError.validation('invalid_phone_number', `"${raw}" is not a valid phone number`);
    }
    return PhoneNumber.fromE164(parsed.number);
  }
}

