import { randomBytes, scrypt as scryptCallback, timingSafeEqual } from 'node:crypto';
import { promisify } from 'node:util';

import { Injectable } from '@nestjs/common';

import { PasswordHasher } from '../../application/ports/password-hasher.port';

const scrypt = promisify(scryptCallback) as (
  password: string,
  salt: Buffer,
  keylen: number,
) => Promise<Buffer>;

const KEY_LENGTH = 64;

/** `PasswordHasher` backed by Node's built-in `crypto.scrypt` (no bcrypt/argon2 native dependency,
 * per the port's own doc-comment). Stored form is `scrypt$<saltHex>$<hashHex>` so the salt travels
 * with the hash and `verify` never needs a second lookup. */
@Injectable()
export class ScryptPasswordHasher implements PasswordHasher {
  async hash(plainPassword: string): Promise<string> {
    const salt = randomBytes(16);
    const derivedKey = await scrypt(plainPassword, salt, KEY_LENGTH);
    return `scrypt$${salt.toString('hex')}$${derivedKey.toString('hex')}`;
  }

  async verify(plainPassword: string, passwordHash: string): Promise<boolean> {
    const parts = passwordHash.split('$');
    if (parts.length !== 3 || parts[0] !== 'scrypt') {
      return false;
    }
    const [, saltHex, hashHex] = parts;
    const salt = Buffer.from(saltHex, 'hex');
    const expected = Buffer.from(hashHex, 'hex');
    const actual = await scrypt(plainPassword, salt, expected.length);
    return actual.length === expected.length && timingSafeEqual(actual, expected);
  }
}

