import { Mapper, UniqueEntityId } from '@memories/shared/kernel';

import { UserProfile } from '../../domain/user-profile';

import { UserProfileOrmEntity } from './user-profile.orm-entity';

export class UserProfileMapper implements Mapper<UserProfile, UserProfileOrmEntity> {
  toDomain(raw: UserProfileOrmEntity): UserProfile {
    return UserProfile.create(
      {
        accountId: raw.accountId,
        fullName: raw.fullName,
        email: raw.email,
        avatarId: raw.avatarId,
        dateOfBirth: raw.dateOfBirth,
        address: raw.address,
        createdBy: raw.createdBy,
        createdAt: raw.createdAt,
        updatedBy: raw.updatedBy,
        updatedAt: raw.updatedAt,
        deletedBy: raw.deletedBy,
        deletedAt: raw.deletedAt,
      },
      new UniqueEntityId(raw.id),
    );
  }

  toPersistence(domain: UserProfile): UserProfileOrmEntity {
    const entity = new UserProfileOrmEntity();
    entity.id = domain.id.toValue();
    entity.accountId = domain.accountId;
    entity.fullName = domain.fullName;
    entity.email = domain.email;
    entity.avatarId = domain.avatarId;
    entity.dateOfBirth = domain.dateOfBirth;
    entity.address = domain.address;
    entity.createdBy = domain.audit.createdBy;
    entity.createdAt = domain.audit.createdAt;
    entity.updatedBy = domain.audit.updatedBy;
    entity.updatedAt = domain.audit.updatedAt;
    entity.deletedBy = domain.audit.deletedBy;
    entity.deletedAt = domain.audit.deletedAt;
    return entity;
  }

