import {
  ACCOUNT_PHONE_SEARCH,
  USER_PROFILE_LOOKUP,
  USER_PROFILE_PROVISIONER,
} from '@memories/platform/security';
import { ID_GENERATOR, UuidGenerator } from '@memories/shared/kernel';
import { Global, Module } from '@nestjs/common';
import { TypeOrmModule } from '@nestjs/typeorm';

import { CreateUserProfileUseCase } from './application/use-cases/create-user-profile.use-case';
import { DeleteUserProfileUseCase } from './application/use-cases/delete-user-profile.use-case';
import { GetUserProfileUseCase } from './application/use-cases/get-user-profile.use-case';
import { ListUserProfilesUseCase } from './application/use-cases/list-user-profiles.use-case';
import { UpdateUserProfileUseCase } from './application/use-cases/update-user-profile.use-case';
import { USER_PROFILE_REPOSITORY } from './domain/user-profile.repository';
import { UserProfileLookupService } from './infrastructure/contracts/user-profile-lookup.service';
import { UserProfileProvisionerService } from './infrastructure/contracts/user-profile-provisioner.service';
import { TypeOrmUserProfileRepository } from './infrastructure/persistence/typeorm-user-profile.repository';
import { UserProfileOrmEntity } from './infrastructure/persistence/user-profile.orm-entity';
import { UserProfileController } from './presentation/http/user-profile.controller';

/**
 * User Profiles bounded context (task.md §4). Marked `@Global()` — together with `IdentityAccessModule`
 * also being `@Global()` — so the two modules can exchange the `ACCOUNT_LOOKUP` /
 * `USER_PROFILE_LOOKUP` / `USER_PROFILE_PROVISIONER` / `ACCOUNT_PHONE_SEARCH` ports declared in
 * `@memories/platform/security` purely through Nest DI, WITHOUT either module's `.module.ts`
 * importing the other's `public-api.ts` — that would make `libs/modules/identity-access` and
 * `libs/modules/user-profiles` cyclically dependent at the TypeScript module-graph level, which
 * `npm run test:architecture` forbids (dependency-cruiser rule "no circular dependencies").
 * `AccountPhoneSearchService` itself is bound in `IdentityAccessModule`, not here.
 */
@Global()
@Module({
  imports: [TypeOrmModule.forFeature([UserProfileOrmEntity])],
  controllers: [UserProfileController],
  providers: [
    CreateUserProfileUseCase,
    GetUserProfileUseCase,
    ListUserProfilesUseCase,
    UpdateUserProfileUseCase,
    DeleteUserProfileUseCase,
    { provide: USER_PROFILE_REPOSITORY, useClass: TypeOrmUserProfileRepository },
    { provide: ID_GENERATOR, useClass: UuidGenerator },
    { provide: USER_PROFILE_LOOKUP, useClass: UserProfileLookupService },
    { provide: USER_PROFILE_PROVISIONER, useClass: UserProfileProvisionerService },
  ],
  exports: [USER_PROFILE_LOOKUP, USER_PROFILE_PROVISIONER, ACCOUNT_PHONE_SEARCH],
})
export class UserProfilesModule {}

