import { ApiProperty } from '@nestjs/swagger';
import { IsEnum, IsString, MaxLength, MinLength } from 'class-validator';

import { Portal } from '../../domain/sessions/portal';

/** Backend maps `portal` to the required permission itself — never accepted as a permission code
 * directly from the client (task.md §9/§10, VR-002). */
export class LoginDto {
  @ApiProperty({ example: '0912345678' })
  @IsString()
  @MaxLength(32)
  phone!: string;

  @ApiProperty()
  @IsString()
  @MinLength(1)
  @MaxLength(255)
  password!: string;

  @ApiProperty({ enum: Portal })
  @IsEnum(Portal)
  portal!: Portal;
}

