import { PaginatedResult, UseCase } from '@memories/shared/kernel';
import { Inject, Injectable } from '@nestjs/common';

import { AccountStatus } from '../../domain/accounts/account-status';
import { ACCOUNT_REPOSITORY, AccountRepository } from '../../domain/accounts/account.repository';

export interface ListAccountsInput {
  status?: AccountStatus;
  provider?: string;
  phoneSearch?: string;
  page: number;
  pageSize: number;
  sortBy: 'createdAt' | 'updatedAt';
  sortDirection: 'ASC' | 'DESC';
}

export interface AccountSummary {
  id: string;
  status: AccountStatus;
  phone: string | null;
  createdAt: Date;
  updatedAt: Date;
}

@Injectable()
export class ListAccountsUseCase implements UseCase<ListAccountsInput, PaginatedResult<AccountSummary>> {
  constructor(@Inject(ACCOUNT_REPOSITORY) private readonly accounts: AccountRepository) {}

  async execute(input: ListAccountsInput): Promise<PaginatedResult<AccountSummary>> {
    const { items, total } = await this.accounts.list(input);
    const summaries = items.map(({ account, phone }) => ({
      id: account.id.toValue(),
      status: account.status,
      phone,
      createdAt: account.audit.createdAt,
      updatedAt: account.audit.updatedAt,
    }));
    return PaginatedResult.of(summaries, total, { page: input.page, pageSize: input.pageSize });
  }
}

