import { Repository, UniqueEntityId } from '@memories/shared/kernel';

import { UserProfile } from './user-profile';

export interface UserProfileListFilter {
  fullNameSearch?: string | undefined;
  emailSearch?: string | undefined;
  /** Account IDs matching a phone search, resolved up-front via the `ACCOUNT_PHONE_SEARCH` port
   * (identity-access query contract, task.md §17 "Search phone thông qua identity-access query
   * contract") — kept out of this repository so `user-profiles` never queries identity-access's
   * tables directly. */
  accountIdsMatchingPhone?: string[] | undefined;
  page: number;
  pageSize: number;
  sortBy: 'createdAt' | 'updatedAt' | 'fullName';
  sortDirection: 'ASC' | 'DESC';
}

export interface UserProfileRepository extends Repository<UserProfile> {
  findByAccountId(accountId: string): Promise<UserProfile | null>;
  existsByAccountId(accountId: string): Promise<boolean>;
  list(filter: UserProfileListFilter): Promise<{ items: UserProfile[]; total: number }>;
}

export const USER_PROFILE_REPOSITORY = Symbol('USER_PROFILE_REPOSITORY');

