import { MediaAsset } from '../src/domain/media-asset/media-asset';
import { MediaAssetStatus } from '../src/domain/media-asset/media-asset-status';

function buildAsset(status = MediaAssetStatus.Pending): MediaAsset {
  return MediaAsset.create({
    ownerId: 'owner-1',
    bucket: 'private-originals',
    objectKey: 'cards/asset.png',
    mimeType: 'image/png',
    sizeBytes: 1024,
    status,
  });
}

describe('MediaAsset', () => {
  it('transitions from uploaded to processing to ready', () => {
    const asset = buildAsset();

    asset.markProcessing();
    expect(asset.status).toBe(MediaAssetStatus.Processing);

    asset.markReady('processed/cards/asset.png');
    expect(asset.status).toBe(MediaAssetStatus.Ready);
    expect(asset.processedObjectKey).toBe('processed/cards/asset.png');
  });

  it('rejects marking an uploaded (not yet processing) asset as ready', () => {
    const asset = buildAsset(MediaAssetStatus.Pending);

    expect(() => asset.markReady('processed/x')).toThrow(/Cannot mark asset/);
  });

  it('treats re-entering processing on an already-ready asset as a no-op (idempotent redelivery)', () => {
    const asset = buildAsset(MediaAssetStatus.Ready);

    asset.markProcessing();

    expect(asset.status).toBe(MediaAssetStatus.Ready);
  });

  it('records which job now owns the processing state when a jobId is given', () => {
    const asset = buildAsset();

    asset.markProcessing('job-1');

    expect(asset.currentJobId).toBe('job-1');
  });

  it('does not touch currentJobId when re-entering processing on an already-ready asset', () => {
    const asset = buildAsset(MediaAssetStatus.Ready);

    asset.markProcessing('job-2');

    expect(asset.currentJobId).toBeUndefined();
  });

  it('marks a processing asset as failed with a reason', () => {
    const asset = buildAsset(MediaAssetStatus.Processing);

    asset.markFailed('processing_failed_after_retries');

    expect(asset.status).toBe(MediaAssetStatus.Failed);
    expect(asset.failureReason).toBe('processing_failed_after_retries');
  });

  it('never pulls an already-ready asset back to failed (stale/redelivered failure report)', () => {
    const asset = buildAsset(MediaAssetStatus.Ready);

    asset.markFailed('processing_failed_after_retries');

    expect(asset.status).toBe(MediaAssetStatus.Ready);
    expect(asset.failureReason).toBeUndefined();
  });
});

