import { StorageBucket } from '@memories/platform/storage';

import { CreateMediaAssetUseCase } from '../src/application/use-cases/create-media-asset.use-case';
import { MediaAssetStatus } from '../src/domain/media-asset/media-asset-status';

function buildUseCase() {
  const mediaAssets = { findById: jest.fn(), save: jest.fn(), delete: jest.fn() };
  const storage = {
    createPresignedUploadUrl: jest.fn().mockResolvedValue({
      url: 'https://s3.example.com/presigned-put',
      bucket: 'memories-private-originals',
      objectKey: 'owner-1/generated-id.png',
      expiresAt: new Date('2026-01-01T00:15:00Z'),
    }),
  };
  const idGenerator = { generate: jest.fn().mockReturnValue('generated-id') };
  const useCase = new CreateMediaAssetUseCase(
    mediaAssets as never,
    storage as never,
    idGenerator as never,
  );
  return { useCase, mediaAssets, storage, idGenerator };
}

describe('CreateMediaAssetUseCase', () => {
  it('persists a pending MediaAsset and returns a presigned upload URL', async () => {
    const { useCase, mediaAssets, storage } = buildUseCase();

    const result = await useCase.execute({
      ownerId: 'owner-1',
      mimeType: 'image/png',
      sizeBytes: 2048,
    });

    expect(storage.createPresignedUploadUrl).toHaveBeenCalledWith({
      bucket: StorageBucket.PrivateOriginals,
      objectKey: 'owner-1/generated-id.png',
      contentType: 'image/png',
      contentLength: 2048,
    });
    expect(mediaAssets.save).toHaveBeenCalledWith(
      expect.objectContaining({ status: MediaAssetStatus.Pending, ownerId: 'owner-1' }),
    );
    expect(result).toEqual({
      mediaAssetId: 'generated-id',
      uploadUrl: 'https://s3.example.com/presigned-put',
      objectKey: 'owner-1/generated-id.png',
      expiresAt: new Date('2026-01-01T00:15:00Z'),
    });
  });

  it('derives the object key extension from the MIME type so confirm-upload can validate it', async () => {
    const { useCase, storage } = buildUseCase();
    storage.createPresignedUploadUrl.mockResolvedValueOnce({
      url: 'https://s3.example.com/presigned-put',
      bucket: 'memories-private-originals',
      objectKey: 'owner-1/generated-id.webp',
      expiresAt: new Date('2026-01-01T00:15:00Z'),
    });

    await useCase.execute({ ownerId: 'owner-1', mimeType: 'image/webp', sizeBytes: 2048 });

    expect(storage.createPresignedUploadUrl).toHaveBeenCalledWith(
      expect.objectContaining({ objectKey: 'owner-1/generated-id.webp' }),
    );
  });

  it('rejects an unsupported MIME type before issuing a presigned URL', async () => {
    const { useCase, storage } = buildUseCase();

    await expect(
      useCase.execute({ ownerId: 'owner-1', mimeType: 'application/pdf', sizeBytes: 2048 }),
    ).rejects.toThrow(/not allowed/);
    expect(storage.createPresignedUploadUrl).not.toHaveBeenCalled();
  });

  it('rejects an oversized file before issuing a presigned URL', async () => {
    const { useCase, storage } = buildUseCase();

    await expect(
      useCase.execute({
        ownerId: 'owner-1',
        mimeType: 'image/png',
        sizeBytes: 21 * 1024 * 1024,
      }),
    ).rejects.toThrow(/exceeds the maximum/);
    expect(storage.createPresignedUploadUrl).not.toHaveBeenCalled();
  });
});

