import { createAuditableProps } from '@memories/shared/kernel';

import { Account } from '../src/domain/accounts/account';
import { AccountStatus } from '../src/domain/accounts/account-status';

const NOW = new Date('2026-01-01T00:00:00Z');

function buildAccount(status = AccountStatus.Active): Account {
  return Account.create({
    status,
    tokenVersion: 0,
    ...createAuditableProps(null, NOW),
  });
}

describe('Account', () => {
  it('can authenticate only when ACTIVE and not deleted', () => {
    expect(buildAccount(AccountStatus.Active).canAuthenticate()).toBe(true);
    expect(buildAccount(AccountStatus.Inactive).canAuthenticate()).toBe(false);
    expect(buildAccount(AccountStatus.Locked).canAuthenticate()).toBe(false);
  });

  it('cannot authenticate once soft deleted, even if ACTIVE', () => {
    const account = buildAccount(AccountStatus.Active);

    account.softDelete('admin-1', NOW);

    expect(account.canAuthenticate()).toBe(false);
    expect(account.isDeleted).toBe(true);
  });

  it('rejects deleting an already-deleted account', () => {
    const account = buildAccount();
    account.softDelete('admin-1', NOW);

    expect(() => account.softDelete('admin-1', NOW)).toThrow(/already deleted/);
  });

  it('bumps tokenVersion so previously issued access tokens can be treated as stale', () => {
    const account = buildAccount();

    account.incrementTokenVersion('admin-1', NOW);

    expect(account.tokenVersion).toBe(1);
  });

  it('activate/lock/deactivate transition status and stamp the actor/time', () => {
    const account = buildAccount(AccountStatus.Active);
    const later = new Date('2026-01-02T00:00:00Z');

    account.lock('admin-1', later);

    expect(account.status).toBe(AccountStatus.Locked);
    expect(account.audit.updatedBy).toBe('admin-1');
    expect(account.audit.updatedAt).toEqual(later);
  });
});

