import { AuthProvider } from '../src/domain/auth-identities/auth-provider';

const NOW = new Date('2026-01-01T00:00:00Z');

describe('AuthIdentity', () => {
  it('requires a phone identifier and password hash for LOCAL provider', () => {
    expect(() =>
      AuthIdentity.create({
        accountId: 'account-1',
        provider: AuthProvider.Local,
        identifier: null,
        providerSubject: null,
        passwordHash: 'hash',
        verifiedAt: null,
        ...createAuditableProps(null, NOW),
      }),
    ).toThrow(/phone/i);

    expect(() =>
      AuthIdentity.create({
        accountId: 'account-1',
        provider: AuthProvider.Local,
        identifier: '+84912345678',
        providerSubject: null,
        passwordHash: null,
        verifiedAt: null,
        ...createAuditableProps(null, NOW),
      }),
    ).toThrow(/password/i);
  });

  it('allows a social provider without an identifier/password (providerSubject instead)', () => {
    const identity = AuthIdentity.create({
      accountId: 'account-1',
      provider: AuthProvider.Google,
      identifier: null,
      providerSubject: 'google-sub-1',
      passwordHash: null,
      verifiedAt: null,
      ...createAuditableProps(null, NOW),
    });

    expect(identity.providerSubject).toBe('google-sub-1');
  });

  it('rejects changing the password on a non-LOCAL identity', () => {
    const identity = AuthIdentity.create({
      accountId: 'account-1',
      provider: AuthProvider.Google,
      identifier: null,
      providerSubject: 'google-sub-1',
      passwordHash: null,
      verifiedAt: null,
      ...createAuditableProps(null, NOW),
    });

    expect(() => identity.changePasswordHash('new-hash', null, NOW)).toThrow(/does not support/);
  });

  it('changes the password hash for a LOCAL identity and stamps the actor/time', () => {
    const identity = AuthIdentity.create({
      accountId: 'account-1',
      provider: AuthProvider.Local,
      identifier: '+84912345678',
      providerSubject: null,
      passwordHash: 'old-hash',
      verifiedAt: null,
      ...createAuditableProps(null, NOW),
    });
    const later = new Date('2026-01-02T00:00:00Z');

    identity.changePasswordHash('new-hash', 'admin-1', later);

    expect(identity.passwordHash).toBe('new-hash');
    expect(identity.audit.updatedBy).toBe('admin-1');
    expect(identity.audit.updatedAt).toEqual(later);
  });
});

