describe('PhoneNumber', () => {
  it('accepts a valid E.164 number', () => {
    expect(PhoneNumber.fromE164('+84912345678').value).toBe('+84912345678');
  });

  it.each(['0912345678', '+84', 'not-a-phone', '+0912345678'])(
    'rejects a non-E.164 value: %s',
    (raw) => {
      expect(() => PhoneNumber.fromE164(raw)).toThrow(/not a valid E\.164/);
    },
  );

  it('treats two PhoneNumber instances with the same value as equal', () => {
    expect(PhoneNumber.fromE164('+84912345678').equals(PhoneNumber.fromE164('+84912345678'))).toBe(true);
  });
});

