import { ScryptPasswordHasher } from '../src/infrastructure/security/scrypt-password-hasher';

describe('ScryptPasswordHasher', () => {
  const hasher = new ScryptPasswordHasher();

  it('never stores the plain password in the hash', async () => {
    const hash = await hasher.hash('correct horse battery staple');
    expect(hash).not.toContain('correct horse battery staple');
  });

  it('verifies a correct password against its own hash', async () => {
    const hash = await hasher.hash('s3cr3t-password');
    await expect(hasher.verify('s3cr3t-password', hash)).resolves.toBe(true);
  });

  it('rejects an incorrect password', async () => {
    const hash = await hasher.hash('s3cr3t-password');
    await expect(hasher.verify('wrong-password', hash)).resolves.toBe(false);
  });

  it('produces a different hash each time (random salt) even for the same password', async () => {
    const [first, second] = await Promise.all([hasher.hash('same-password'), hasher.hash('same-password')]);
    expect(first).not.toBe(second);
  });

  it('rejects a malformed stored hash instead of throwing', async () => {
    await expect(hasher.verify('anything', 'not-a-valid-hash')).resolves.toBe(false);
  });
});

