import { createAuditableProps } from '@memories/shared/kernel';

import { AuthIdentity } from '../src/domain/auth-identities/auth-identity';
import { AuthProvider } from '../src/domain/auth-identities/auth-provider';
import { LocalAuthenticationProvider } from '../src/infrastructure/security/local-authentication.provider';

const NOW = new Date('2026-01-01T00:00:00Z');

function buildIdentity(): AuthIdentity {
  return AuthIdentity.create(
    {
      accountId: 'account-1',
      provider: AuthProvider.Local,
      identifier: '+84912345678',
      providerSubject: null,
      passwordHash: 'stored-hash',
      verifiedAt: null,
      ...createAuditableProps(null, NOW),
    },
    { toValue: () => 'identity-1' } as never,
  );
}

function buildProvider() {
  const authIdentities = { findByProviderAndIdentifier: jest.fn() };
  const passwordHasher = { hash: jest.fn(), verify: jest.fn() };
  const provider = new LocalAuthenticationProvider(authIdentities as never, passwordHasher as never);
  return { provider, authIdentities, passwordHasher };
}

describe('LocalAuthenticationProvider', () => {
  it('resolves the account when the phone and password match', async () => {
    const { provider, authIdentities, passwordHasher } = buildProvider();
    authIdentities.findByProviderAndIdentifier.mockResolvedValue(buildIdentity());
    passwordHasher.verify.mockResolvedValue(true);

    const result = await provider.authenticate({
      provider: AuthProvider.Local,
      identifier: '+84912345678',
      plainPassword: 'correct-password',
    });

    expect(result).toEqual({ accountId: 'account-1', authIdentityId: 'identity-1' });
  });

  it('throws the same generic error when the phone is unknown (no account enumeration)', async () => {
    const { provider, authIdentities } = buildProvider();
    authIdentities.findByProviderAndIdentifier.mockResolvedValue(null);

    await expect(
      provider.authenticate({ provider: AuthProvider.Local, identifier: '+84900000000', plainPassword: 'x' }),
    ).rejects.toThrow('Invalid phone or password');
  });

  it('throws the same generic error when the password is wrong', async () => {
    const { provider, authIdentities, passwordHasher } = buildProvider();
    authIdentities.findByProviderAndIdentifier.mockResolvedValue(buildIdentity());
    passwordHasher.verify.mockResolvedValue(false);

    await expect(
      provider.authenticate({ provider: AuthProvider.Local, identifier: '+84912345678', plainPassword: 'wrong' }),
    ).rejects.toThrow('Invalid phone or password');
  });
});

