import { createAuditableProps, UniqueEntityId } from '@memories/shared/kernel';

import { Permission } from '../src/domain/permissions/permission';
import { Role } from '../src/domain/roles/role';
import { PermissionCheckerService } from '../src/infrastructure/security/permission-checker.service';

const NOW = new Date('2026-01-01T00:00:00Z');

function buildRole(id: string, code: string): Role {
  return Role.create({ code, name: code, ...createAuditableProps(null, NOW) }, new UniqueEntityId(id));
}

function buildPermission(id: string, code: string): Permission {
  return Permission.create(
    { code, description: code, ...createAuditableProps(null, NOW) },
    new UniqueEntityId(id),
  );
}

function buildService() {
  const accountRoles = { listRoleIdsForAccount: jest.fn() };
  const roles = { list: jest.fn() };
  const rolePermissions = { listPermissionIdsForRoles: jest.fn() };
  const permissions = { list: jest.fn() };
  const service = new PermissionCheckerService(
    accountRoles as never,
    roles as never,
    rolePermissions as never,
    permissions as never,
  );
  return { service, accountRoles, roles, rolePermissions, permissions };
}

describe('PermissionCheckerService', () => {
  it('resolves roles and permissions through AccountRole -> RolePermission -> Permission', async () => {
    const { service, accountRoles, roles, rolePermissions, permissions } = buildService();
    accountRoles.listRoleIdsForAccount.mockResolvedValue(['role-admin']);
    roles.list.mockResolvedValue([buildRole('role-admin', 'ADMIN'), buildRole('role-other', 'OTHER')]);
    rolePermissions.listPermissionIdsForRoles.mockResolvedValue(['perm-1']);
    permissions.list.mockResolvedValue([
      buildPermission('perm-1', 'portal.admin.access'),
      buildPermission('perm-2', 'account.read'),
    ]);

    const resolved = await service.resolvePermissions('account-1');

    expect(resolved).toEqual({ roles: ['ADMIN'], permissions: ['portal.admin.access'] });
  });

  it('returns nothing granted for an Account with no assigned role', async () => {
    const { service, accountRoles } = buildService();
    accountRoles.listRoleIdsForAccount.mockResolvedValue([]);

    const resolved = await service.resolvePermissions('account-1');

    expect(resolved).toEqual({ roles: [], permissions: [] });
  });

  it('hasPermissions is true only when every requested permission is granted', async () => {
    const { service, accountRoles, roles, rolePermissions, permissions } = buildService();
    accountRoles.listRoleIdsForAccount.mockResolvedValue(['role-admin']);
    roles.list.mockResolvedValue([buildRole('role-admin', 'ADMIN')]);
    rolePermissions.listPermissionIdsForRoles.mockResolvedValue(['perm-1']);
    permissions.list.mockResolvedValue([buildPermission('perm-1', 'portal.admin.access')]);

    await expect(service.hasPermissions('account-1', ['portal.admin.access'])).resolves.toBe(true);
    await expect(
      service.hasPermissions('account-1', ['portal.admin.access', 'account.read']),
    ).resolves.toBe(false);
  });

  it('treats a permission code that is not seeded as not granted, never implicitly allowed', async () => {
    const { service, accountRoles, roles, rolePermissions, permissions } = buildService();
    accountRoles.listRoleIdsForAccount.mockResolvedValue(['role-admin']);
    roles.list.mockResolvedValue([buildRole('role-admin', 'ADMIN')]);
    rolePermissions.listPermissionIdsForRoles.mockResolvedValue([]);
    permissions.list.mockResolvedValue([]);

    await expect(service.hasPermissions('account-1', ['portal.admin.access'])).resolves.toBe(false);
  });
});

