import 'reflect-metadata';
import { writeFileSync } from 'node:fs';
import { resolve } from 'node:path';

import { AppConfig } from '@memories/platform/configuration';
import { ConfigService } from '@nestjs/config';
import { NestFactory } from '@nestjs/core';

import { AppModule } from './app.module';
import { applyGlobalPrefix } from './configure-app';
import { buildOpenApiDocument } from './openapi';

/**
 * Generates the OpenAPI artifact as a standalone command — no `app.listen()`, no production
 * deployment needed. Requires the same infrastructure `apps/api` needs to boot (Postgres/Redis;
 * see `docker/docker-compose.yml --profile infrastructure`), since route/DTO metadata is only
 * available once the full Nest DI graph is built, but never binds an HTTP port.
 *
 * Usage: `npm run export:openapi -- [output path, default ./openapi.json]`
 */
async function main(): Promise<void> {
  const outputPath = resolve(process.cwd(), process.argv[2] ?? 'openapi.json');

  const app = await NestFactory.create(AppModule, { logger: false });
  const appConfig = app.get(ConfigService).getOrThrow<AppConfig>('app');

  // Must happen before buildOpenApiDocument: NestJS's Swagger module bakes in whatever the
  // global prefix already is at document-build time, same as the real running server (main.ts
  // calls this before app.listen()) — otherwise the exported contract documents unprefixed
  // paths (`/media`) that don't match the real, deployed endpoint (`/api/v1/media`).
  applyGlobalPrefix(app, appConfig);

  const document = buildOpenApiDocument(app, appConfig);
  writeFileSync(outputPath, JSON.stringify(document, null, 2));

  await app.close();
  // eslint-disable-next-line no-console -- CLI feedback, not application logging
  console.log(`Wrote OpenAPI document to ${outputPath}`);
}

main().catch((error) => {
  // eslint-disable-next-line no-console -- CLI feedback, not application logging
  console.error('Failed to export OpenAPI document:', error);
  process.exit(1);
});
